const exchangeNeonSession=async()=>{const tokenResponse=await fetch(`${authUrl.replace(/\/$/,"")}/token`,{method:"GET",credentials:"include",headers:{"Accept":"application/json"}});const tokenData=await tokenResponse.json().catch(()=>({}));const token=typeof tokenData==="string"?tokenData:tokenData.token||tokenData.access_token||tokenData.data?.token||tokenData.data?.access_token||tokenData.session?.access_token;if(!tokenResponse.ok)throw new Error(tokenData.message||tokenData.error||`Neon JWT request failed (HTTP ${tokenResponse.status}).`);if(!token||typeof token!=="string")throw new Error("Neon did not return a JWT. Please sign in again and retry.");const response=await fetch("/api/auth/neon-session",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+token},credentials:"same-origin"});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"This Neon account is not authorized for the portal.");setAuth(data.user);setAuthStage("login");setAuthPassword("");setAuthError("");setAuthNotice("");};
